import { renderHook, waitFor } from '@testing-library/react'
import { describe, it, expect, vi, beforeEach } from 'vitest'
import { useBooks } from './useBooks'
import * as api from '../api'

describe('useBooks', () => {
  beforeEach(() => {
    vi.restoreAllMocks()
  })

  it('starts in loading state before data resolves', () => {
    vi.spyOn(api, 'getBooks').mockReturnValue(new Promise(() => {}))
    const { result } = renderHook(() => useBooks())
    expect(result.current.loading).toBe(true)
    expect(result.current.data).toBeUndefined()
    expect(result.current.error).toBeUndefined()
  })

  it('populates data and clears loading on success', async () => {
    const books = [{ id: 1, title: 'Dune' }, { id: 2, title: 'Foundation' }]
    vi.spyOn(api, 'getBooks').mockResolvedValue(books)
    const { result } = renderHook(() => useBooks())
    await waitFor(() => expect(result.current.loading).toBe(false))
    expect(result.current.data).toEqual(books)
    expect(result.current.error).toBeUndefined()
  })

  it('sets error and clears loading when getBooks rejects', async () => {
    const err = new Error('fetch failed')
    vi.spyOn(api, 'getBooks').mockRejectedValue(err)
    const { result } = renderHook(() => useBooks())
    await waitFor(() => expect(result.current.loading).toBe(false))
    expect(result.current.error).toBe(err)
    expect(result.current.data).toBeUndefined()
  })

  it('sets data to empty array when getBooks resolves with []', async () => {
    vi.spyOn(api, 'getBooks').mockResolvedValue([])
    const { result } = renderHook(() => useBooks())
    await waitFor(() => expect(result.current.loading).toBe(false))
    expect(result.current.data).toEqual([])
    expect(result.current.error).toBeUndefined()
  })

  it('calls getBooks exactly once on mount', async () => {
    const spy = vi.spyOn(api, 'getBooks').mockResolvedValue([])
    const { result } = renderHook(() => useBooks())
    await waitFor(() => expect(result.current.loading).toBe(false))
    expect(spy).toHaveBeenCalledTimes(1)
  })

  it('does not call getBooks again on rerender', async () => {
    const spy = vi.spyOn(api, 'getBooks').mockResolvedValue([])
    const { result, rerender } = renderHook(() => useBooks())
    await waitFor(() => expect(result.current.loading).toBe(false))
    rerender()
    expect(spy).toHaveBeenCalledTimes(1)
  })
})
